export const typographyThemeBefore = "@import \"tailwindcss\";\n@import \"tw-animate-css\";\n@import \"./catalog/mechanisms/theme/tokens.css\";\n@import \"./catalog/mechanisms/pane-material/pane-material.css\";\n@import \"./catalog/mechanisms/control-feedback/control-feedback.css\";\n@import \"./catalog/mechanisms/navigation-selection/navigation-selection.css\";\n@import \"./catalog/mechanisms/typography/typography.css\";\n@import \"./catalog/mechanisms/layout/layout.css\";\n@import \"./catalog/foundations/field-well/field-well.css\";\n@import \"./catalog/foundations/search-field/search-field.css\";\n@import \"./catalog/mechanisms/structured-content/structured-content.css\";\n@import \"./catalog/foundations/place/place.css\";\n@import \"./catalog/mechanisms/control-measure/control-measure.css\";\n@import \"./catalog/compositions/place-heading/place-heading.css\";\n@import \"./catalog/mechanisms/media/media.css\";\n@import \"./catalog/mechanisms/surface-chrome/surface-chrome.css\";\n@import \"./catalog/mechanisms/surface-reading/surface-reading.css\";\n@import \"./catalog/compositions/toolbar-layout/toolbar-layout.css\";\n@import \"./catalog/foundations/scroll-edges/scroll-edges.css\";\n@import \"./catalog/mechanisms/anchored-surface/anchored-surface.css\";\n@import \"./catalog/mechanisms/reading/reading.css\";\n@import \"./catalog/mechanisms/catalog-profile/catalog-profile.css\";\n@import \"./catalog/mechanisms/catalog-shell/catalog-shell.css\";\n@import \"./catalog/mechanisms/catalog-search/catalog-search.css\";\n@import \"./catalog/mechanisms/catalog-media/catalog-media.css\";\n@source \"./\";\n@custom-variant dark (&:where([data-theme=\"dark\"], [data-theme=\"dark\"] *));\n@theme inline {\n  --color-background:var(--background); --color-foreground:var(--foreground);\n  --color-card:var(--card); --color-card-foreground:var(--card-foreground);\n  --color-popover:var(--popover); --color-popover-foreground:var(--popover-foreground);\n  --color-primary:var(--primary); --color-primary-foreground:var(--primary-foreground);\n  --color-primary-text:var(--primary-text);\n  --color-secondary:var(--secondary); --color-secondary-foreground:var(--secondary-foreground);\n  --color-muted:var(--muted); --color-muted-foreground:var(--muted-foreground);\n  --color-accent:var(--accent); --color-accent-foreground:var(--accent-foreground);\n  --color-destructive:var(--destructive); --color-border:var(--border); --color-separator:var(--separator);\n  --color-destructive-text:color-mix(in oklab,var(--destructive) 65%,var(--foreground));\n  --color-warning:var(--warning); --color-success:var(--positive);\n  --color-input:var(--border); --color-control:var(--control); --color-ring:var(--ring);\n  --color-choice-outline:var(--choice-outline);\n  --color-sidebar:var(--sidebar); --color-sidebar-foreground:var(--sidebar-foreground);\n  --color-sidebar-primary:var(--sidebar-primary); --color-sidebar-primary-foreground:var(--sidebar-primary-foreground);\n  --color-sidebar-accent:var(--sidebar-accent); --color-sidebar-accent-foreground:var(--sidebar-accent-foreground);\n  --color-sidebar-border:var(--sidebar-border); --color-sidebar-ring:var(--sidebar-ring);\n  --radius-sm:var(--radius); --radius-md:var(--radius); --radius-lg:var(--radius); --radius-xl:var(--radius); --radius-2xl:var(--radius);\n}\n@utility tm-control {\n  transition:color var(--dur-feedback) var(--ease-tm);\n  & > :is([data-button-content],[data-grouped-content]),\n  &[data-slot=\"sidebar-menu-button\"]:not(:has(> [data-button-content])) > * { transition:transform var(--dur-snap) var(--ease-tm); }\n  /* Pointer hover must not turn neutral or destructive actions into primary ones.\n     Keep their semantic ink; tooltips, press feedback and keyboard focus remain. */\n  &:is(button,a,label[data-choice-row])[data-pressed]:not(:disabled):not([aria-disabled=\"true\"]):not([data-drawer-grip]) {\n    & > :is([data-button-content],[data-grouped-content]),\n    &[data-slot=\"sidebar-menu-button\"]:not(:has(> [data-button-content])) > * { transform:scale(var(--press-scale)); }\n  }\n  &:focus-visible { outline:2px solid var(--ring); outline-offset:var(--focus-ring-offset,3px); }\n  @media (prefers-reduced-motion:reduce) {\n    & > :is([data-button-content],[data-grouped-content]),\n    &[data-slot=\"sidebar-menu-button\"]:not(:has(> [data-button-content])) > * { transform:none!important; }\n  }\n}\n@utility tm-tinted {\n  color:color-mix(in oklab,var(--tone) 60%,var(--foreground));\n}\n@utility tm-face {\n  background-color:color-mix(in oklab,var(--face-tone,var(--primary-text)) 14%,var(--secondary));\n  &::after { border-color:color-mix(in oklab,var(--face-tone,var(--primary-text)) 30%,var(--border)); }\n  @media (prefers-contrast:more) { &::after { border-color:var(--foreground); } }\n}\n:root { --warning:oklch(.52 .12 85); --choice-outline:var(--muted-foreground); }\n@media (prefers-color-scheme:dark) { :root:not([data-theme=\"light\"]) { --warning:oklch(.85 .16 90); } }\n:root[data-theme=\"dark\"] { --warning:oklch(.85 .16 90); }\n@layer base {\n  * { box-sizing:border-box; border-color:var(--border); }\n  [hidden] { display:none!important; }\n  html { background:var(--background); color:var(--foreground); font-family:var(--font-sans); font-size:calc(100% * var(--text-scale, 1)); }\n  body { margin:0; min-width:320px; font-size:var(--text-body); line-height:var(--text-body--line-height); }\n  button,input,textarea { font:inherit; } button { cursor:pointer; } button:disabled { cursor:default; }\n  input,textarea { min-width:0; } h1,h2,h3,p { margin:0; } a { color:inherit; }\n  :focus-visible { outline:2px solid var(--ring); outline-offset:var(--focus-ring-offset,3px); }\n  @media (prefers-reduced-motion:reduce) { *,*::before,*::after { animation:none!important; transition:none!important; scroll-behavior:auto!important; } }\n}\n@layer components {\n  [data-control-chevron] { color:var(--muted-foreground); flex-shrink:0; }\n  [data-slot=\"input-group-control\"] { min-height:2.75rem; }\n  .required { color:var(--destructive); }\n  .bank-face { width:var(--face-size,2rem); height:var(--face-size,2rem); color:var(--muted-foreground); }\n  .bank-face[data-compact] { --face-size:1.5rem; }\n  .bank-face [data-face-glyph] { font-size:calc(var(--face-size,2rem) * .6); line-height:1; }\n  .bank-face[data-face-kind=\"flag\"] [data-face-glyph] { font-family:\"Apple Color Emoji\",\"Segoe UI Emoji\",\"Noto Color Emoji\",sans-serif; }\n  .bank-face svg { width:55%; height:55%; }\n  .bank-face[data-tone=\"warning\"] { --face-tone:var(--warning); color:var(--face-tone); }\n  .bank-face[data-tone=\"error\"] { --face-tone:var(--destructive); color:var(--face-tone); }\n  .bank-status { display:flex; align-items:center; gap:.5rem; font-size:var(--text-body); color:var(--muted-foreground); }\n  .bank-status svg { width:1rem; height:1rem; flex-shrink:0; }\n}\n@media (prefers-contrast:more) { :root { --border:var(--foreground); --separator:var(--foreground); --muted-foreground:var(--foreground); } }\n";
